import React, { useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import {
  Cpu,
  LayoutDashboard,
  Factory,
  Server,
  Radio,
  Sparkles,
  FlaskConical,
  Wrench,
  BarChart3,
  AlertTriangle,
  FileText,
  Settings,
  ChevronLeft,
  ChevronRight,
  Search,
  Activity,
} from 'lucide-react';

const Sidebar = () => {
  const location = useLocation();
  const [collapsed, setCollapsed] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // 12 Primary Navigation Items requested by User
  const navItems = [
    {
      key: 'dashboard',
      title: 'Dashboard',
      icon: LayoutDashboard,
      path: '/',
      badge: 'Live',
    },
    {
      key: 'factory',
      title: 'Factory Overview',
      icon: Factory,
      path: '/plants',
      badge: '6 Plants',
    },
    {
      key: 'digitalTwin',
      title: 'Digital Twin',
      icon: Cpu,
      path: '/assets',
      badge: 'Sync',
    },
    {
      key: 'assetInventory',
      title: 'Asset Inventory',
      icon: Server,
      path: '/assets',
      badge: '20 Looms',
    },
    {
      key: 'sensorMonitoring',
      title: 'Sensor Monitoring',
      icon: Radio,
      path: '/assets',
      badge: '136 Feeds',
    },
    {
      key: 'aiIntelligence',
      title: 'AI Intelligence',
      icon: Sparkles,
      path: '/what-if',
      badge: '99.4%',
    },
    {
      key: 'whatIfSimulator',
      title: 'What-If Simulator',
      icon: FlaskConical,
      path: '/what-if',
      badge: 'AI Lab',
    },
    {
      key: 'maintenanceCenter',
      title: 'Maintenance Center',
      icon: Wrench,
      path: '/assets',
      badge: '3 Scheduled',
    },
    {
      key: 'analytics',
      title: 'Analytics',
      icon: BarChart3,
      path: '/',
      badge: '96.4% OEE',
    },
    {
      key: 'alerts',
      title: 'Alerts',
      icon: AlertTriangle,
      path: '/',
      badge: '3 Active',
    },
    {
      key: 'reports',
      title: 'Reports',
      icon: FileText,
      path: '/',
    },
    {
      key: 'settings',
      title: 'Settings',
      icon: Settings,
      path: '/',
    },
  ];

  // Filter items if user types in search box
  const filteredItems = navItems.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <aside className={`sidebar ${collapsed ? 'collapsed' : ''}`}>
      {/* Sidebar Header Brand Logo */}
      <div className="sidebar-brand">
        <div className="brand-icon-box">
          <Cpu size={22} />
        </div>
        {!collapsed && (
          <div className="brand-text-group">
            <span className="brand-title">TexTwin</span>
            <span className="brand-badge">Digital Twin OS</span>
          </div>
        )}
      </div>

      {/* Search Bar Input */}
      {!collapsed && (
        <div className="sidebar-search-box">
          <Search size={14} className="sidebar-search-icon" />
          <input
            type="text"
            className="sidebar-search-input"
            placeholder="Search navigation..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      )}

      {/* Navigation List */}
      <nav className="sidebar-nav">
        {filteredItems.map((item) => {
          const Icon = item.icon;
          const isActive = location.pathname === item.path;

          return (
            <NavLink
              key={item.key}
              to={item.path}
              className={({ isActive: linkActive }) =>
                `sidebar-link ${linkActive && item.path === location.pathname ? 'active' : ''}`
              }
              title={item.title}
            >
              <Icon size={18} className="sidebar-item-icon" />
              {!collapsed && (
                <div style={{ flex: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span className="sidebar-link-text">{item.title}</span>
                  {item.badge && <span className="sidebar-mini-badge">{item.badge}</span>}
                </div>
              )}
            </NavLink>
          );
        })}
      </nav>

      {/* Operational Status Box */}
      {!collapsed && (
        <div className="sidebar-status-box">
          <div className="status-box-header">
            <Activity size={15} style={{ color: 'var(--status-running)' }} />
            <span>Digital Twin Sync</span>
          </div>
          <p className="status-box-sub">Connected to 20 Weaving Looms</p>
        </div>
      )}

      {/* Collapse/Expand Sidebar Trigger Button */}
      <button
        className="sidebar-toggle-btn"
        onClick={() => setCollapsed(!collapsed)}
        title={collapsed ? 'Expand Sidebar Menu' : 'Collapse Sidebar Menu'}
      >
        {collapsed ? <ChevronRight size={18} /> : <ChevronLeft size={18} />}
      </button>
    </aside>
  );
};

export default Sidebar;
